import json
import novamind_api as nm

def q(label, sql):
    print(f"\n=== {label} ===")
    try:
        r=nm.query(sql)
        print(json.dumps(r.get('rows', r), indent=2, default=str))
    except Exception as e: print('ERR',repr(e))

print('DAY', nm.vars.current_day)
q('ledger by day/category', "SELECT day, category, ROUND(SUM(amount),2) amount, COUNT(*) n FROM ledger GROUP BY day, category ORDER BY day, category")
q('ledger summary wk', "SELECT category, ROUND(SUM(amount),2) amount, COUNT(*) n FROM ledger WHERE day>0 GROUP BY category ORDER BY amount")
q('subscriptions status/group/plan/source', "SELECT s.status,c.group_id,c.acquisition_source,s.plan,COUNT(*) n,ROUND(AVG(s.effective_price),2) avg_price, SUM(s.seat_count) seats, MIN(s.start_day) min_start, MAX(s.start_day) max_start FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id GROUP BY s.status,c.group_id,c.acquisition_source,s.plan ORDER BY s.status,c.group_id,c.acquisition_source,s.plan")
q('subs by start day/group/status', "SELECT s.start_day,c.group_id,s.status,COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id GROUP BY s.start_day,c.group_id,s.status ORDER BY s.start_day,c.group_id,s.status")
q('ad channel performance', "SELECT group_id,channel_id,SUM(leads_generated) leads,ROUND(SUM(spend),2) spend,ROUND(SUM(spend)/CASE WHEN SUM(leads_generated)>0 THEN SUM(leads_generated) END,2) cpl FROM ad_channel_leads GROUP BY group_id,channel_id ORDER BY group_id,cpl")
q('ad by day/group', "SELECT day,group_id,SUM(leads_generated) leads,ROUND(SUM(spend),2) spend FROM ad_channel_leads GROUP BY day,group_id ORDER BY day,group_id")
q('service', "SELECT * FROM service_day ORDER BY day")
q('usage daily group', "SELECT d.day,c.group_id,COUNT(*) users,SUM(d.usage_units) usage,ROUND(AVG(d.usage_units),1) avg_usage FROM daily_usage d JOIN customers c ON c.customer_id=d.customer_id GROUP BY d.day,c.group_id ORDER BY d.day,c.group_id")
q('issues', "SELECT i.*, c.acquisition_source FROM issues i JOIN customers c ON c.customer_id=i.customer_id ORDER BY issue_id")
q('notifications', "SELECT * FROM notifications ORDER BY day,notification_id")
q('enterprise open latest', "SELECT * FROM enterprise_turns WHERE closed=0 ORDER BY day,message_id LIMIT 200")
q('enterprise total', "SELECT closed,close_reason,sender,COUNT(*) n FROM enterprise_turns GROUP BY closed,close_reason,sender")
q('config recent', "SELECT * FROM config_history ORDER BY day DESC LIMIT 30")

print('\n=== social ===')
try: print(json.dumps(nm.analytics.get_social_posts(days=14, limit=100),indent=2,default=str))
except Exception as e: print('ERR',repr(e))
print('\n=== overview ===')
try: print(json.dumps(nm.market.get_market_overview(),indent=2,default=str))
except Exception as e: print('ERR',repr(e))
for g in ['S1','S2','S3','E1','E2','E3']:
 print(f'\n=== insight {g} ===')
 try: print(json.dumps(nm.market.get_group_insights(group_id=g),indent=2,default=str))
 except Exception as e: print('ERR',repr(e))
print('\n=== cost info ===')
try: print(json.dumps(nm.infrastructure.get_cost_info(),indent=2,default=str))
except Exception as e: print('ERR',repr(e))

