import novamind_api as nm, json

def q(label,sql):
 print('\n###',label)
 try:
  r=nm.query(sql); print(json.dumps(r.get('rows',r),indent=2,default=str))
 except Exception as e: print('ERR',e)
print('DAY',nm.vars.current_day)
for label,sql in [
('ledger daily category',"select day,category,round(sum(amount),2) amount,count(*) n from ledger group by day,category order by day,category"),
('ledger week',"select case when day<=7 then 'w1' else 'w2' end wk, category,round(sum(amount),2) amount from ledger where day>0 group by wk,category order by wk,category"),
('subs status group plan',"select c.group_id,s.status,s.plan,count(*) n,sum(s.seat_count) seats,round(avg(s.effective_price),2) avg_eff,round(min(s.effective_price),2) min_eff,round(max(s.effective_price),2) max_eff from subscriptions s join customers c on c.customer_id=s.customer_id group by c.group_id,s.status,s.plan order by c.group_id,s.status,s.plan"),
('new customers by day source status',"select c.created_day,c.group_id,c.acquisition_source,s.status,s.plan,count(*) n from customers c join subscriptions s on s.customer_id=c.customer_id group by c.created_day,c.group_id,c.acquisition_source,s.status,s.plan order by c.created_day,c.group_id,c.acquisition_source,s.status"),
('ad leads daily',"select day,channel_id,group_id,sum(leads_generated) leads,sum(spend) spend from ad_channel_leads group by day,channel_id,group_id order by day,channel_id,group_id"),
('issues',"select i.*,c.acquisition_source from issues i left join customers c on i.customer_id=c.customer_id order by issue_id"),
('posts',"select * from social_media_posts order by day desc,post_id desc limit 100"),
('enterprise',"select * from enterprise_turns where closed=0 order by day,message_id limit 100"),
('usage daily',"select day,sum(usage_units) usage,count(distinct customer_id) users,round(avg(usage_units),1) avgu,max(usage_units) maxu from daily_usage group by day order by day"),
('service',"select * from service_day order by day"),
('overrides',"select * from config_overrides order by day desc limit 20"),
('discovery',"select * from segment_discovery"),
('notifs',"select * from notifications order by day desc limit 100"),
]:q(label,sql)
print('\n### market overview')
try: print(json.dumps(nm.market.get_market_overview(),indent=2,default=str))
except Exception as e: print(e)
for g in ['S1','S2','S3','E1','E2','E3']:
 print('\n### insight',g)
 try: print(json.dumps(nm.market.get_group_insights(group_id=g),indent=2,default=str))
 except Exception as e: print(e)
print('\n### research projects')
try: print(json.dumps(nm.research.list_research_projects(),indent=2,default=str))
except Exception as e: print(e)
PY
./novamind-operation python /tmp/diag.py > /tmp/diag.out
wc -l /tmp/diag.out

