cat > /tmp/analyze.py <<'PY'
import novamind_api as nm, json

def q(sql, title):
 print('\n###', title)
 try:
  r=nm.query(sql); print(json.dumps(r.get('rows'),indent=2,default=str));
  if r.get('warning'): print('WARN',r['warning'])
 except Exception as e: print('ERR',e)

print('DAY',nm.vars.current_day)
for g in ['S1','S2','S3','E1','E2','E3']:
 print('\n### INSIGHT',g)
 try: print(json.dumps(nm.market.get_group_insights(group_id=g),indent=2,default=str))
 except Exception as e: print('ERR',e)
try: print('\n### MARKET\n',json.dumps(nm.market.get_market_overview(),indent=2,default=str))
except Exception as e: print(e)
try: print('\n### SOCIAL\n',json.dumps(nm.analytics.get_social_posts(days=28,limit=100),indent=2,default=str))
except Exception as e: print(e)
q("SELECT status, COUNT(*) n, SUM(seat_count) seats FROM subscriptions GROUP BY status",'sub status')
q("SELECT c.group_id,s.plan,s.status,COUNT(*) n,SUM(s.seat_count) seats,AVG(s.listed_price) avg_list,AVG(s.promotion) avg_promo,AVG(s.effective_price) avg_eff,MIN(s.start_day) minstart,MAX(s.start_day) maxstart FROM subscriptions s JOIN customers c USING(customer_id) GROUP BY c.group_id,s.plan,s.status ORDER BY 1,2,3",'subs grouped')
q("SELECT s.subscription_id,s.customer_id,c.created_day,c.acquisition_source,c.group_id,s.plan,s.listed_price,s.promotion,s.effective_price,s.start_day,s.billing_day_mod30,s.seat_count,s.status,s.end_day FROM subscriptions s JOIN customers c USING(customer_id) ORDER BY s.subscription_id",'all subs')
q("SELECT day,category,ROUND(SUM(amount),2) amount,COUNT(*) n FROM ledger WHERE day>=21 GROUP BY day,category ORDER BY day,category",'daily ledger week')
q("SELECT category,ROUND(SUM(amount),2) amount,COUNT(*) n FROM ledger WHERE day>=21 GROUP BY category ORDER BY category",'ledger totals week')
q("SELECT * FROM ad_channel_leads WHERE day>=21 ORDER BY day",'ad leads')
q("SELECT * FROM enterprise_turns WHERE closed=0 ORDER BY day,message_id LIMIT 100",'open enterprise')
q("SELECT * FROM issues ORDER BY rowid DESC LIMIT 100",'issues')
q("SELECT * FROM service_day WHERE day>=21 ORDER BY day",'service day')
q("SELECT * FROM config_history WHERE day>=20 ORDER BY day",'config hist')
q("SELECT * FROM config_overrides ORDER BY rowid DESC LIMIT 50",'overrides')
q("SELECT * FROM notifications ORDER BY rowid DESC LIMIT 50",'notifications')
PY
./novamind-operation python /tmp/analyze.py > /tmp/analyze.out
wc -l /tmp/analyze.out
cat /tmp/analyze.out

