cat docs/tables/config_history.json docs/tables/config_overrides.json && cat > /tmp/history.py <<'PY'
import novamind_api as nm, json
qs={
'config':"SELECT * FROM config_history ORDER BY day,id",
'overrides':"SELECT * FROM config_overrides ORDER BY id",
'ads_by_period':'''SELECT CASE WHEN day<=7 THEN '1-7' WHEN day<=14 THEN '8-14' WHEN day<=21 THEN '15-21' WHEN day<=28 THEN '22-28' ELSE '29-35' END period,channel_id,group_id,SUM(leads_generated) leads,SUM(spend) spend FROM ad_channel_leads GROUP BY 1,2,3 ORDER BY 1,2,3''',
'leads_by_period':'''SELECT CASE WHEN c.created_day<=7 THEN '1-7' WHEN c.created_day<=14 THEN '8-14' WHEN c.created_day<=21 THEN '15-21' WHEN c.created_day<=28 THEN '22-28' ELSE '29-35' END period,c.group_id,c.acquisition_source,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) canc,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,ROUND(AVG(CASE WHEN s.status IN ('subscribed','cancelled') THEN s.effective_price END),2) avgprice FROM customers c JOIN subscriptions s USING(customer_id) GROUP BY 1,2,3 ORDER BY 1,2,3''',
'all_ledger':'''SELECT CASE WHEN day<=7 THEN '1-7' WHEN day<=14 THEN '8-14' WHEN day<=21 THEN '15-21' WHEN day<=28 THEN '22-28' ELSE '29-35' END period,category,ROUND(SUM(amount),2) amt FROM ledger WHERE day>0 GROUP BY 1,2 ORDER BY 1,2'''
}
for n,q in qs.items():
 print('\n###',n)
 try: print(json.dumps(nm.query(q)['rows'],indent=2))
 except Exception as e: print(e)
PY
./novamind-operation python /tmp/history.py

cat docs/tables/daily_usage.json && cat > /tmp/usage.py <<'PY'
import novamind_api as nm,json
for name,q in {
'u35':'''SELECT d.customer_id,c.group_id,s.plan,d.usage_units FROM daily_usage d JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE d.day=35 AND s.status='subscribed' ORDER BY d.usage_units DESC''',
'agg':'''SELECT d.customer_id,ROUND(AVG(d.usage_units),1) avgu,MAX(d.usage_units) maxu,COUNT(*) days FROM daily_usage d JOIN subscriptions s USING(customer_id) WHERE d.day>=29 AND s.status='subscribed' GROUP BY 1 ORDER BY avgu DESC'''
}.items():
 print(name)
 try: print(json.dumps(nm.query(q)['rows'],indent=2))
 except Exception as e: print(e)
PY
./novamind-operation python /tmp/usage.py

