import novamind_api as nm, json
qs={
'cohort source':"SELECT c.created_day,c.acquisition_source,s.status,COUNT(*) n,ROUND(AVG(s.effective_price),2) price FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id WHERE c.created_day>=43 GROUP BY c.created_day,c.acquisition_source,s.status ORDER BY c.created_day,c.acquisition_source,s.status",
'usage active':"SELECT u.day,COUNT(*) users,ROUND(AVG(u.usage_units),2) avg_usage,MAX(u.usage_units) max_usage,SUM(CASE WHEN u.usage_units>=300 THEN 1 ELSE 0 END) at300,ROUND(SUM(u.usage_units),0) units FROM daily_usage u JOIN subscriptions s ON s.customer_id=u.customer_id AND s.status='subscribed' WHERE u.day>=43 GROUP BY u.day ORDER BY u.day",
'usage dist49':"SELECT CASE WHEN usage_units=0 THEN '0' WHEN usage_units<=50 THEN '1-50' WHEN usage_units<=100 THEN '51-100' WHEN usage_units<=150 THEN '101-150' WHEN usage_units<=200 THEN '151-200' WHEN usage_units<300 THEN '201-299' ELSE '300' END bucket,COUNT(*) n,SUM(usage_units) units FROM daily_usage WHERE day=49 GROUP BY bucket ORDER BY MIN(usage_units)",
'billing future pattern':"SELECT billing_day_mod30,COUNT(*) n,ROUND(SUM(effective_price),0) revenue FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30 ORDER BY billing_day_mod30",
'issue by cohort':"SELECT i.open_day,c.created_day,COUNT(*) n FROM issues i JOIN customers c ON c.customer_id=i.customer_id WHERE i.open_day>=47 GROUP BY i.open_day,c.created_day ORDER BY i.open_day,c.created_day",
}
for lab,sql in qs.items():
 print('\n###',lab);print(json.dumps(nm.query(sql)['rows'],indent=2))

