import novamind_api as nm, json
queries={
'ledger_daily': "SELECT day, category, ROUND(SUM(amount),2) amt FROM ledger WHERE day BETWEEN 50 AND 56 GROUP BY day,category ORDER BY day,category",
'ledger_net': "SELECT day, ROUND(SUM(amount),2) net, ROUND(SUM(CASE WHEN amount>0 THEN amount ELSE 0 END),2) revenue, ROUND(SUM(CASE WHEN amount<0 THEN amount ELSE 0 END),2) costs FROM ledger WHERE day BETWEEN 50 AND 56 GROUP BY day ORDER BY day",
'leads_daily': "SELECT day, channel_id, group_id, leads_generated, spend FROM ad_channel_leads WHERE day BETWEEN 50 AND 56 ORDER BY day,channel_id,group_id",
'signups_daily_source': "SELECT c.created_day day,c.acquisition_source,c.group_id,COUNT(*) n, ROUND(SUM(s.effective_price*s.seat_count),2) signup_value FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id WHERE c.created_day BETWEEN 50 AND 56 AND s.status='subscribed' GROUP BY c.created_day,c.acquisition_source,c.group_id ORDER BY day,c.acquisition_source",
'created_outcome': "SELECT c.created_day day,c.acquisition_source,c.group_id,s.status,COUNT(*) n FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id WHERE c.created_day BETWEEN 50 AND 56 GROUP BY c.created_day,c.acquisition_source,c.group_id,s.status ORDER BY day,c.acquisition_source,s.status",
'issues_daily': "SELECT open_day, COUNT(*) opened, SUM(CASE WHEN status='open' THEN 1 ELSE 0 END) still_open, ROUND(AVG(CASE WHEN status='resolved' THEN resolved_day-open_day END),3) avg_resolve_days, SUM(CASE WHEN status='resolved' AND resolved_day=open_day THEN 1 ELSE 0 END) same_day, SUM(CASE WHEN status='resolved' AND resolved_day=open_day+1 THEN 1 ELSE 0 END) next_day FROM issues WHERE open_day BETWEEN 43 AND 56 GROUP BY open_day ORDER BY open_day",
'open_issues_age': "SELECT days_open,COUNT(*) n,MIN(open_day) min_open,MAX(open_day) max_open FROM issues WHERE status='open' GROUP BY days_open ORDER BY days_open DESC",
'usage_daily': "SELECT day,total_usage_units,p95_ms,error_rate,downtime_minutes,capacity_tier,capacity_units FROM service_day WHERE day BETWEEN 43 AND 56 ORDER BY day",
'active_by_cohort_price': "SELECT s.start_day,s.listed_price,s.plan,COUNT(*) n,ROUND(SUM(s.effective_price),2) monthly FROM subscriptions s WHERE s.status='subscribed' GROUP BY s.start_day,s.listed_price,s.plan ORDER BY s.start_day",
'active_by_group_plan': "SELECT c.group_id,s.plan,s.listed_price,COUNT(*) n,ROUND(SUM(s.effective_price),2) monthly FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id,s.plan,s.listed_price ORDER BY c.group_id,s.plan,s.listed_price",
'config_overrides': "SELECT id,day,tool_name,settings_json FROM config_overrides ORDER BY id DESC LIMIT 20",
'config_hist': "SELECT * FROM config_history WHERE day BETWEEN 49 AND 56 ORDER BY day",
'posts': "SELECT post_id,day,content FROM social_media_posts WHERE day BETWEEN 50 AND 56 ORDER BY day,post_id",
'ent_open': "SELECT * FROM enterprise_turns WHERE closed=0 ORDER BY day,message_id LIMIT 100",
'ledger_total': "SELECT ROUND(SUM(amount),2) net, ROUND(SUM(CASE WHEN amount>0 THEN amount ELSE 0 END),2) inflow, ROUND(SUM(CASE WHEN amount<0 THEN amount ELSE 0 END),2) outflow FROM ledger"
}
for name,q in queries.items():
 print('\n###',name)
 try:
  r=nm.query(q)
  print(json.dumps(r.get('rows',r),indent=2))
 except Exception as e: print('ERROR',e)
print('\n### social_api')
try: print(json.dumps(nm.analytics.get_social_posts(days=14,limit=100),indent=2))
except Exception as e: print('ERROR',e)
print('\n### cost_info')
try: print(json.dumps(nm.infrastructure.get_cost_info(),indent=2))
except Exception as e: print('ERROR',e)

