import novamind_api as nm
qs={
'active by billmod':"SELECT billing_day_mod30 mod,COUNT(*) n,ROUND(SUM(effective_price*seat_count),2) book FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30 ORDER BY billing_day_mod30",
'active by start':"SELECT start_day,COUNT(*) n,ROUND(SUM(effective_price*seat_count),2) book FROM subscriptions WHERE status='subscribed' GROUP BY start_day ORDER BY start_day",
'payments by day 0-84':"SELECT day,ROUND(SUM(amount),2) revenue FROM ledger WHERE category='subscription_payment' GROUP BY day ORDER BY day",
'config overrides':"SELECT * FROM config_overrides ORDER BY rowid",
'config history':"SELECT * FROM config_history WHERE day>=70 ORDER BY day",
'issues old exact':"SELECT COUNT(*) n,MIN(open_day) oldest,ROUND(AVG(days_open),2) avgage FROM issues WHERE status='open' AND days_open>0",
'customer created ent':"SELECT group_id,created_day,COUNT(*) n FROM customers WHERE customer_type='large' AND created_day>=70 GROUP BY group_id,created_day ORDER BY created_day,group_id",
}
for k,s in qs.items():
 print('\n###',k)
 try:
  for r in nm.query(s)['rows']: print(r)
 except Exception as e: print('ERR',e)

