import novamind_api as nm,json

def q(label,sql):
 print('\n###',label)
 try:
  for x in nm.query(sql)['rows']: print(x)
 except Exception as e: print('ERR',e)

q('cohort statuses 43-61',"""SELECT start_day,status,COUNT(*) n FROM subscriptions WHERE start_day BETWEEN 43 AND 61 GROUP BY start_day,status ORDER BY start_day,status""")
q('cancel by original cohort all end days',"""SELECT start_day,end_day,COUNT(*) n FROM subscriptions WHERE start_day BETWEEN 43 AND 61 AND status='cancelled' GROUP BY start_day,end_day ORDER BY start_day,end_day""")
q('active billing schedule and book',"""SELECT billing_day_mod30,COUNT(*) n,ROUND(SUM(effective_price*seat_count),0) book FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30 ORDER BY billing_day_mod30""")
q('next 30 day payments if active',"""SELECT ((billing_day_mod30-(91%30)+30)%30) days_ahead, COUNT(*) n,ROUND(SUM(effective_price*seat_count),0) book FROM subscriptions WHERE status='subscribed' GROUP BY days_ahead ORDER BY days_ahead""")
q('active S1 by start day recent',"""SELECT start_day,COUNT(*) n,ROUND(SUM(effective_price),0) book FROM subscriptions s JOIN customers c USING(customer_id) WHERE status='subscribed' AND c.group_id='S1' GROUP BY start_day ORDER BY start_day""")
q('all generated by group/status days85+',"""SELECT c.group_id,c.customer_type,s.status,COUNT(*) n FROM customers c LEFT JOIN subscriptions s USING(customer_id) WHERE c.created_day>=85 GROUP BY c.group_id,c.customer_type,s.status ORDER BY c.customer_type,c.group_id,s.status""")
q('S1 created conversion daily',"""SELECT c.created_day,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) sub,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,ROUND(100.0*SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END)/COUNT(*),1) conv FROM customers c LEFT JOIN subscriptions s USING(customer_id) WHERE c.group_id='S1' AND c.created_day>=77 GROUP BY c.created_day ORDER BY c.created_day""")
q('expenses avg current week',"""SELECT category,ROUND(AVG(x),2) avgdaily FROM (SELECT day,category,SUM(-amount) x FROM ledger WHERE amount<0 AND day BETWEEN 85 AND 91 GROUP BY day,category) GROUP BY category""")
print('\n### overview')
try:
 ov=nm.market.get_market_overview(); print(json.dumps(ov,indent=2)); groups=[x['group_id'] for x in ov.get('known_groups',[])]
except Exception as e: print(e);groups=[]
for g in groups:
 print('\n### insight',g)
 try: print(json.dumps(nm.market.get_group_insights(group_id=g),indent=2))
 except Exception as e: print(e)

