arguments.command:
./novamind-operation python-c "import novamind_api as nm, json; qs={
'enterprise':\"SELECT COUNT(*) n FROM enterprise_turns WHERE closed=0\",
'active_by_group_plan':\"SELECT c.group_id,s.plan,COUNT(*) n,SUM(s.price) mrr FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='active' GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan\",
'issues':\"SELECT c.group_id, CASE WHEN i.resolved_at IS NULL THEN 'open' ELSE 'resolved' END st, COUNT(*) n FROM customer_issues i JOIN customers c ON c.customer_id=i.customer_id GROUP BY c.group_id,st ORDER BY c.group_id,st\",
'stale':\"SELECT c.group_id, CAST(julianday(105)-julianday(i.created_at) AS INT) age,COUNT(*) n FROM customer_issues i JOIN customers c ON c.customer_id=i.customer_id WHERE i.resolved_at IS NULL GROUP BY c.group_id,age ORDER BY c.group_id,age\"};
for k,q in qs.items():
 print('---',k); print(json.dumps(nm.query(q),default=str))"

./novamind-operation python-c "import novamind_api as nm, json
qs={
'active_by_group_plan':\"SELECT c.group_id,s.plan,COUNT(*) n,SUM(s.effective_price*s.seat_count) mrr FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='active' GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan\",
'issues':\"SELECT c.group_id, CASE WHEN i.status='open' THEN 'open' ELSE 'resolved' END st, COUNT(*) n FROM customer_issues i JOIN customers c ON c.customer_id=i.customer_id GROUP BY c.group_id,st ORDER BY c.group_id,st\",
'stale':\"SELECT c.group_id, i.days_open age,COUNT(*) n FROM customer_issues i JOIN customers c ON c.customer_id=i.customer_id WHERE i.status='open' GROUP BY c.group_id,age ORDER BY c.group_id,age\"}
for k,q in qs.items():
 print('---',k)
 try: print(json.dumps(nm.query(q),default=str))
 except Exception as e: print(type(e).__name__,e)"

./novamind-operation python-c "import novamind_api as nm, json
qs={
'issue_flow':\"SELECT d.day, COALESCE(o.opened,0) opened, COALESCE(r.resolved,0) resolved FROM (SELECT open_day day FROM issues WHERE open_day BETWEEN 90 AND 105 UNION SELECT resolved_day day FROM issues WHERE resolved_day BETWEEN 90 AND 105) d LEFT JOIN (SELECT open_day day,COUNT(*) opened FROM issues WHERE open_day BETWEEN 90 AND 105 GROUP BY open_day)o ON d.day=o.day LEFT JOIN (SELECT resolved_day day,COUNT(*) resolved FROM issues WHERE resolved_day BETWEEN 90 AND 105 GROUP BY resolved_day)r ON d.day=r.day GROUP BY d.day ORDER BY d.day\",
'next_book':\"SELECT billing_day_mod30,SUM(effective_price*seat_count) gross,COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30 ORDER BY billing_day_mod30\",
'ledger_week':\"SELECT category,SUM(amount) amount,COUNT(*) n FROM ledger WHERE day BETWEEN 99 AND 105 GROUP BY category ORDER BY category\",
'ads':\"SELECT day,SUM(revenue) revenue FROM ads_revenue WHERE day>=90 GROUP BY day ORDER BY day\",
'config_override':\"SELECT * FROM config_overrides ORDER BY rowid DESC LIMIT 30\",
'service':\"SELECT * FROM service_day WHERE day>=90 ORDER BY day\"
}
for k,q in qs.items():
 print('---',k)
 try: print(json.dumps(nm.query(q),default=str))
 except Exception as e: print(type(e).__name__,e)"

