arguments.command:
./novamind-operation python-c "import novamind_api as nm, json
qs={
'config_hist':\"SELECT day,operations_spend,development_spend,capacity_tier,price_A,price_B,price_C FROM config_history ORDER BY day\",
'issue_period':\"SELECT open_day day,COUNT(*) opened FROM issues GROUP BY open_day ORDER BY open_day\",
'resolve_period':\"SELECT resolved_day day,COUNT(*) resolved FROM issues WHERE resolved_day IS NOT NULL GROUP BY resolved_day ORDER BY resolved_day\",
'cash_daily':\"SELECT day,SUM(amount) net FROM ledger GROUP BY day ORDER BY day\",
'cohort_all':\"SELECT start_day,SUM(CASE WHEN status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN status='cancelled' THEN 1 ELSE 0 END) cancelled,SUM(CASE WHEN status='lost' THEN 1 ELSE 0 END) lost FROM subscriptions GROUP BY start_day ORDER BY start_day\"}
for k,q in qs.items():
 print('---',k)
 try: print(json.dumps(nm.query(q),default=str))
 except Exception as e: print(type(e).__name__,e)"

./novamind-operation python-c "import novamind_api as nm, json
qs={
'cancels':\"SELECT end_day,start_day,plan,COUNT(*) n FROM subscriptions WHERE status='cancelled' AND end_day BETWEEN 99 AND 105 GROUP BY end_day,start_day,plan ORDER BY end_day,start_day,plan\",
'payment_type':\"SELECT l.day, CASE WHEN s.start_day=l.day THEN 'signup' ELSE 'renewal' END typ, SUM(l.amount) amt,COUNT(*) n FROM ledger l JOIN subscriptions s ON s.subscription_id=l.reference_id WHERE l.category='subscription_payment' AND l.day BETWEEN 99 AND 105 GROUP BY l.day,typ ORDER BY l.day,typ\"
}
for k,q in qs.items():
 print('---',k)
 try: print(json.dumps(nm.query(q),default=str))
 except Exception as e: print(type(e).__name__,e)"

