import novamind_api as nm
qs={
'usage':"SELECT day,COUNT(*) users,SUM(usage_units) usage,AVG(usage_units) avg,MAX(usage_units) mx FROM daily_usage WHERE day>112 GROUP BY day ORDER BY day",
'notifications':"SELECT * FROM notifications WHERE day>105 ORDER BY day",
'research':"SELECT * FROM research_projects",
'config':"SELECT * FROM config_history WHERE day>=105 ORDER BY day",
'posts':"SELECT post_id,day,group_id,customer_id,content FROM social_media_posts WHERE day>105 ORDER BY day DESC,post_id DESC LIMIT 100",
'issue_lifecycle':"SELECT open_day,COUNT(*) opened,SUM(CASE WHEN status='resolved' THEN 1 ELSE 0 END) resolved,AVG(CASE WHEN resolved_day IS NOT NULL THEN resolved_day-open_day END) avgdays,SUM(CASE WHEN status='open' THEN 1 ELSE 0 END) stillopen FROM issues WHERE open_day>105 GROUP BY open_day ORDER BY open_day",
'cancelmods':"SELECT s.billing_day_mod30 mod,COUNT(*) n FROM subscriptions s WHERE s.end_day>112 GROUP BY mod ORDER BY mod",
'mrr':"SELECT SUM(effective_price*seat_count) mrr,COUNT(*) n FROM subscriptions WHERE status='subscribed'"
}
for k,q in qs.items():
 print('\n===',k); r=nm.query(q); print(r.get('rows')); print(r.get('error',''))
for g in ['S1','S2','S3','E1','E2','E3','D_E02','D_E09']:
 try: print('\nINSIGHT',g,nm.market.get_group_insights(group_id=g))
 except Exception as e: print('ERR',g,e)
PY
