arguments.command:
./novamind-operation python-c "import novamind_api as nm
qs={
'start_status':\"SELECT s.start_day,c.group_id,s.status,COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.start_day>=119 GROUP BY s.start_day,c.group_id,s.status ORDER BY s.start_day,c.group_id,s.status\",
'end_status':\"SELECT s.end_day,c.group_id,s.status,COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.end_day>=119 GROUP BY s.end_day,c.group_id,s.status ORDER BY s.end_day,c.group_id,s.status\",
'posts':\"SELECT post_id,day,group_id,substr(content,1,500) content FROM social_media_posts WHERE day>=120 ORDER BY day DESC,post_id DESC LIMIT 50\",
'agentposts':\"SELECT * FROM agent_social_media_posts ORDER BY day DESC LIMIT 10\",
'ledgerweeks':\"SELECT CASE WHEN day BETWEEN 120 AND 126 THEN 'cur' WHEN day BETWEEN 113 AND 119 THEN 'prev' END wk,category,SUM(amount) amt FROM ledger WHERE day BETWEEN 113 AND 126 GROUP BY wk,category ORDER BY wk,category\",
'cancel_cohorts':\"SELECT s.end_day,s.billing_day_mod30,COUNT(*) n,SUM(s.effective_price) rev FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.end_day BETWEEN 120 AND 126 AND c.customer_type='small' GROUP BY s.end_day,s.billing_day_mod30 ORDER BY s.end_day,s.billing_day_mod30\",
'active_age':\"SELECT CAST((126-s.start_day)/30 AS INT) months, COUNT(*) n, SUM(s.effective_price) mrr FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND c.customer_type='small' GROUP BY months ORDER BY months\"
}
for k,q in qs.items():
 print('\\n##',k)
 try: print(nm.query(q)['rows'])
 except Exception as e: print('ERR',e)
"

