import novamind_api as nm,json
qs={
'opened':"SELECT open_day day,COUNT(*) opened FROM issues WHERE open_day BETWEEN 134 AND 140 GROUP BY open_day ORDER BY open_day",
'opened_active_current':"SELECT i.open_day day,COUNT(*) opened FROM issues i JOIN subscriptions s ON s.customer_id=i.customer_id AND s.status='subscribed' WHERE i.open_day BETWEEN 134 AND 140 GROUP BY i.open_day ORDER BY i.open_day",
'open_by_substatus':"SELECT COALESCE(s.status,'none') substatus,i.days_open,COUNT(*) n FROM issues i LEFT JOIN subscriptions s ON s.customer_id=i.customer_id WHERE i.status='open' GROUP BY COALESCE(s.status,'none'),i.days_open ORDER BY substatus,days_open",
'upgrades':"SELECT s.start_day,c.group_id,s.plan,COUNT(*) n,SUM(s.effective_price) revenue FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND s.start_day BETWEEN 134 AND 140 GROUP BY s.start_day,c.group_id,s.plan ORDER BY s.start_day,c.group_id,s.plan",
'futuremods':"SELECT billing_day_mod30,COUNT(*) n,SUM(effective_price*seat_count) amount FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30 ORDER BY billing_day_mod30",
'active_start':"SELECT start_day,plan,COUNT(*) n,SUM(effective_price) mrr FROM subscriptions WHERE status='subscribed' AND start_day BETWEEN 106 AND 140 GROUP BY start_day,plan ORDER BY start_day,plan",
'payments_mod':"SELECT day%30 mod,ROUND(SUM(amount),2) revenue FROM ledger WHERE category='subscription_payment' AND day BETWEEN 111 AND 140 GROUP BY day%30 ORDER BY mod",
'payments30':"SELECT day,ROUND(SUM(amount),2) revenue,COUNT(*) n FROM ledger WHERE category='subscription_payment' AND day BETWEEN 111 AND 140 GROUP BY day ORDER BY day",
}
for k,s in qs.items():
 try: print('\n###',k); print(json.dumps(nm.query(s)['rows'],indent=2))
 except Exception as e: print(repr(e))

