import novamind_api as nm, json
D=nm.vars.current_day; lo=D-6

def q(label,sql):
 print('\n### '+label)
 try:
  r=nm.query(sql); print(json.dumps(r.get('rows',r),indent=2,default=str))
 except Exception as e: print('ERR',repr(e))

print('DAY',D,'WEEK',lo,D)
q('ledger week categories',f"SELECT category,COUNT(*) n,ROUND(SUM(amount),2) amount FROM ledger WHERE day BETWEEN {lo} AND {D} GROUP BY category ORDER BY amount DESC")
q('ledger daily',f"SELECT day,ROUND(SUM(CASE WHEN amount>0 THEN amount ELSE 0 END),2) receipts,ROUND(-SUM(CASE WHEN amount<0 THEN amount ELSE 0 END),2) costs,ROUND(SUM(amount),2) net FROM ledger WHERE day BETWEEN {lo} AND {D} GROUP BY day ORDER BY day")
q('subscription payment daily notes',f"SELECT day,note,COUNT(*) n,ROUND(SUM(amount),2) amount FROM ledger WHERE category='subscription_payment' AND day BETWEEN {lo} AND {D} GROUP BY day,note ORDER BY day,amount DESC LIMIT 200")
q('active by group plan',"SELECT c.group_id,s.plan,COUNT(*) subs,SUM(s.seat_count) seats,ROUND(SUM(s.effective_price*s.seat_count),2) monthly_book,ROUND(AVG(s.effective_price),2) avgprice FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id,s.plan ORDER BY monthly_book DESC")
q('active billing mod',"SELECT billing_day_mod30,COUNT(*) subs,ROUND(SUM(effective_price*seat_count),2) book FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30 ORDER BY billing_day_mod30")
q('new leads current status daily',f"SELECT c.created_day,c.group_id,s.status,s.plan,COUNT(*) n FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day BETWEEN {lo} AND {D} GROUP BY c.created_day,c.group_id,s.status,s.plan ORDER BY c.created_day,c.group_id,s.status,s.plan")
q('new leads totals',f"SELECT c.created_day,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active_now,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) cancelled,SUM(CASE WHEN s.status='subscribed' AND s.plan='A' THEN 1 ELSE 0 END) active_A,SUM(CASE WHEN s.status='subscribed' AND s.plan='B' THEN 1 ELSE 0 END) active_B,SUM(CASE WHEN s.status='subscribed' AND s.plan='C' THEN 1 ELSE 0 END) active_C FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day BETWEEN {lo} AND {D} GROUP BY c.created_day ORDER BY c.created_day")
q('cancels daily group plan agebucket',f"SELECT s.end_day,c.group_id,s.plan,CASE WHEN s.end_day-s.start_day<30 THEN '<30' WHEN s.end_day-s.start_day<60 THEN '30-59' WHEN s.end_day-s.start_day<90 THEN '60-89' WHEN s.end_day-s.start_day<120 THEN '90-119' ELSE '120+' END age,COUNT(*) n,ROUND(SUM(s.effective_price),2) lostbook FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.end_day BETWEEN {lo} AND {D} GROUP BY s.end_day,c.group_id,s.plan,age ORDER BY s.end_day,c.group_id,s.plan,age")
q('cancels summary',f"SELECT c.group_id,s.plan,COUNT(*) n,ROUND(SUM(s.effective_price),2) lostbook,ROUND(AVG(s.end_day-s.start_day),1) avg_age FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.end_day BETWEEN {lo} AND {D} GROUP BY c.group_id,s.plan ORDER BY n DESC")
q('active cohort/start summary',"SELECT start_day,plan,COUNT(*) n,ROUND(SUM(effective_price),2) book FROM subscriptions WHERE status='subscribed' GROUP BY start_day,plan ORDER BY start_day DESC LIMIT 100")
q('issues open active-account ages',"SELECT i.group_id,CASE WHEN i.days_open=0 THEN '0' WHEN i.days_open=1 THEN '1' WHEN i.days_open=2 THEN '2' WHEN i.days_open<=6 THEN '3-6' ELSE '7+' END age,COUNT(*) n FROM issues i JOIN subscriptions s USING(customer_id) WHERE i.status='open' AND s.status='subscribed' GROUP BY i.group_id,age ORDER BY i.group_id,age")
q('issues all open ages',"SELECT group_id,CASE WHEN days_open=0 THEN '0' WHEN days_open=1 THEN '1' WHEN days_open=2 THEN '2' WHEN days_open<=6 THEN '3-6' ELSE '7+' END age,COUNT(*) n FROM issues WHERE status='open' GROUP BY group_id,age ORDER BY group_id,age")
q('issue flow total',f"SELECT x.day,COALESCE(o.opened,0) opened,COALESCE(r.resolved,0) resolved,COALESCE(r.fast,0) fast FROM (SELECT day FROM config_history WHERE day BETWEEN {lo} AND {D})x LEFT JOIN (SELECT open_day day,COUNT(*) opened FROM issues WHERE open_day BETWEEN {lo} AND {D} GROUP BY open_day)o USING(day) LEFT JOIN (SELECT resolved_day day,COUNT(*) resolved,SUM(CASE WHEN days_open<=1 THEN 1 ELSE 0 END) fast FROM issues WHERE resolved_day BETWEEN {lo} AND {D} GROUP BY resolved_day)r USING(day) ORDER BY x.day")
q('issue flow active at end',f"SELECT i.open_day,COUNT(*) opened_for_current_active FROM issues i JOIN subscriptions s USING(customer_id) WHERE s.status='subscribed' AND i.open_day BETWEEN {lo} AND {D} GROUP BY i.open_day ORDER BY i.open_day")
q('service',f"SELECT * FROM service_day WHERE day BETWEEN {lo} AND {D} ORDER BY day")
q('usage daily active/group',f"SELECT d.day,c.group_id,COUNT(*) users,SUM(d.usage_units) usage,ROUND(AVG(d.usage_units),1) avgu FROM daily_usage d JOIN customers c USING(customer_id) WHERE d.day BETWEEN {lo} AND {D} GROUP BY d.day,c.group_id ORDER BY d.day,c.group_id")
q('config',f"SELECT * FROM config_history WHERE day BETWEEN {lo} AND {D} ORDER BY day")
q('notifications',f"SELECT * FROM notifications WHERE day>={lo-7} ORDER BY day,notification_id")
q('enterprise latest open',"WITH z AS (SELECT customer_id,MAX(message_id) mid FROM enterprise_turns GROUP BY customer_id) SELECT e.* FROM enterprise_turns e JOIN z ON e.message_id=z.mid WHERE e.closed=0 ORDER BY e.day,e.message_id LIMIT 100")
q('predictions recent',f"SELECT * FROM predictions WHERE submit_day>={D-35} ORDER BY submit_day,horizon_days")
q('research db',"SELECT * FROM research_projects ORDER BY started_day,tier")
print('\n### COST');
try: print(json.dumps(nm.infrastructure.get_cost_info(),indent=2,default=str))
except Exception as e: print(e)
print('\n### SOCIAL');
try:
 r=nm.analytics.get_social_posts(days=14,limit=200)
 print('total',r.get('total'))
 for p in sorted(r.get('posts',[]),key=lambda x:(x.get('day',0),x.get('post_id',0))):
  print(json.dumps({k:p.get(k) for k in ['post_id','day','group_id','source_group_id','persona_name','content']},default=str))
except Exception as e: print(e)
print('\n### PROJECTS');
try: print(json.dumps(nm.research.list_research_projects(),indent=2,default=str))
except Exception as e: print(e)

