import novamind_api as nm, json

def do(label,fn):
 print('\n##',label)
 try: print(json.dumps(fn(),indent=2,default=str))
 except Exception as e: print('ERR',repr(e))

do('raise quality ladder without making A substitute for B',lambda: nm.pricing.set_model_tiers(A=1,B=3,C=4))
do('quality pulse S1 plus economical D_S07 unlock test',lambda: nm.analytics.set_targeted_dev_spend(targeted_spend={'S1':50000.0,'D_S07':5000.0}))
do('hold ops and zero global dev',lambda: nm.marketing.set_daily_spend(operations=80000.0,development=0.0))
do('reply directly with audited support diagnosis',lambda: nm.marketing.post_social_media(content="Alex, silence isn't acceptable. Our live active-account audit shows zero tickets carried past today, so your Monday report may have hit a broken account-state handoff. Send the ticket ID; we'll trace it, publish the root cause, and fix the path—not just close it.",reply_to_post_id=417))
do('one market discovery option',lambda: nm.market.research_market())

