import novamind_api as nm, json, re
D=nm.vars.current_day

def q(label,sql):
 print('\n##',label)
 try: print(json.dumps(nm.query(sql).get('rows'),indent=2,default=str))
 except Exception as e: print('ERR',e)

q('daily lead outcomes plans 176+',f"SELECT c.created_day,c.group_id,s.plan,s.status,COUNT(*) n FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day BETWEEN 176 AND {D} GROUP BY c.created_day,c.group_id,s.plan,s.status ORDER BY c.created_day,c.group_id,s.status,s.plan")
q('S1 cohorts 146-152 exact',"SELECT c.created_day,s.plan,COUNT(*) total,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) cancelled,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,ROUND(SUM(CASE WHEN s.status='subscribed' THEN s.effective_price ELSE 0 END),0) activebook FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.group_id='S1' AND c.created_day BETWEEN 146 AND 152 GROUP BY c.created_day,s.plan ORDER BY c.created_day,s.plan")
q('cancel book by day and cohort',f"SELECT s.end_day,CASE WHEN s.start_day<100 THEN '<100' WHEN s.start_day<130 THEN '100-129' WHEN s.start_day<146 THEN '130-145' ELSE '146+' END cohort,s.plan,COUNT(*) n,ROUND(SUM(s.effective_price),0) book FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.end_day BETWEEN 176 AND {D} GROUP BY s.end_day,cohort,s.plan ORDER BY s.end_day,cohort,s.plan")
q('ledger daily recent',f"SELECT day,category,ROUND(SUM(amount),0) amt FROM ledger WHERE day BETWEEN 176 AND {D} GROUP BY day,category ORDER BY day,category")
print('\n## overview'); print(json.dumps(nm.market.get_market_overview(),indent=2,default=str))
for g in ['S1','D_S07','D_S10']:
 print('\n## insight',g); print(json.dumps(nm.market.get_group_insights(group_id=g),indent=2,default=str))
print('\n## social summaries')
r=nm.analytics.get_social_posts(days=10,limit=300)
for p in r.get('posts',[]):
 c=p.get('content','')
 if p.get('day',0)>=176:
  print(p.get('post_id'),p.get('day'),p.get('group_id'),c.replace('\n',' ')[:500])

