import novamind_api as nm, json

def q(label, sql):
    print('\n###',label)
    try:
        r=nm.query(sql)
        print(json.dumps(r.get('rows',r), indent=2, default=str))
    except Exception as e: print('ERR',e)

print('DAY',nm.vars.current_day)
q('ledger by day/category 176+', "SELECT day,category,ROUND(SUM(amount),2) amount FROM ledger WHERE day>=176 GROUP BY day,category ORDER BY day,category")
q('ledger weekly', "SELECT CASE WHEN day BETWEEN 183 AND 189 THEN 'this' ELSE 'prior' END wk,category,ROUND(SUM(amount),2) amount FROM ledger WHERE day BETWEEN 176 AND 189 GROUP BY wk,category ORDER BY wk,category")
q('active by group plan', "SELECT c.group_id,s.plan,COUNT(*) n,ROUND(SUM(s.effective_price*s.seat_count),2) mrr, SUM(s.seat_count) seats FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan")
q('lead conversion day/group 176+', "SELECT c.created_day,c.group_id,COUNT(*) leads,SUM(CASE WHEN s.status!='lost' THEN 1 ELSE 0 END) converted,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,ROUND(100.0*SUM(CASE WHEN s.status!='lost' THEN 1 ELSE 0 END)/COUNT(*),1) convpct FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.customer_type='small' AND c.created_day>=176 GROUP BY c.created_day,c.group_id ORDER BY c.created_day,c.group_id")
q('S1 cohort current survival 140+', "SELECT s.start_day,COUNT(*) converted,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) cancelled,ROUND(100.0*SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END)/COUNT(*),1) activepct FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.status!='lost' AND s.start_day BETWEEN 140 AND 189 GROUP BY s.start_day ORDER BY s.start_day")
q('cancellations end day/start ranges', "SELECT s.end_day, CASE WHEN s.start_day<140 THEN '<140' WHEN s.start_day<146 THEN '140-145' WHEN s.start_day<153 THEN '146-152' WHEN s.start_day<160 THEN '153-159' WHEN s.start_day<167 THEN '160-166' ELSE '167+' END cohort, COUNT(*) n, ROUND(SUM(s.effective_price),2) lost_mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.status='cancelled' AND s.end_day>=176 GROUP BY s.end_day,cohort ORDER BY s.end_day,cohort")
q('starts/end book by day', "SELECT d.day,COALESCE(n.n,0) starts,COALESCE(n.mrr,0) new_mrr,COALESCE(x.n,0) cancels,COALESCE(x.mrr,0) lost_mrr FROM (SELECT DISTINCT day FROM ledger WHERE day>=176) d LEFT JOIN (SELECT s.start_day day,COUNT(*) n,ROUND(SUM(s.effective_price),2) mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='small' AND s.status!='lost' AND s.start_day>=176 GROUP BY s.start_day)n ON n.day=d.day LEFT JOIN (SELECT s.end_day day,COUNT(*) n,ROUND(SUM(s.effective_price),2)mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='small' AND s.status='cancelled' AND s.end_day>=176 GROUP BY s.end_day)x ON x.day=d.day ORDER BY d.day")
q('billing next buckets', "SELECT CASE WHEN billing_day_mod30 IN (10,11,12,13,14,15,16) THEN 'next7' ELSE 'other' END bucket,COUNT(*) n,ROUND(SUM(effective_price*seat_count),2) rev FROM subscriptions WHERE status='subscribed' GROUP BY bucket")
q('billing by mod', "SELECT billing_day_mod30,COUNT(*) n,ROUND(SUM(effective_price*seat_count),2) rev FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30 ORDER BY billing_day_mod30")
q('issues dynamics', "SELECT d.day,COALESCE(o.opens,0) opens,COALESCE(r.resolved,0) resolved FROM (SELECT DISTINCT day FROM ledger WHERE day>=176)d LEFT JOIN (SELECT open_day day,COUNT(*) opens FROM issues WHERE open_day>=176 GROUP BY open_day)o ON o.day=d.day LEFT JOIN (SELECT resolved_day day,COUNT(*) resolved FROM issues WHERE resolved_day>=176 GROUP BY resolved_day)r ON r.day=d.day ORDER BY d.day")
q('open issue ages active subs only', "SELECT i.days_open,COUNT(*) n FROM issues i JOIN subscriptions s USING(customer_id) WHERE i.status='open' AND s.status='subscribed' GROUP BY i.days_open ORDER BY i.days_open")
q('service', "SELECT * FROM service_day WHERE day>=176 ORDER BY day")
q('notifications recent', "SELECT * FROM notifications WHERE day>=176 ORDER BY notification_id")
q('enterprise latest', "SELECT t.* FROM enterprise_turns t JOIN (SELECT customer_id,MAX(message_id) mid FROM enterprise_turns GROUP BY customer_id)x ON t.message_id=x.mid WHERE t.closed=0 ORDER BY t.day,t.message_id LIMIT 100")
q('info levels', "SELECT * FROM group_info_levels WHERE info_level>0 ORDER BY group_id")
q('config overrides', "SELECT * FROM config_overrides")

for gid in ['S1','D_S10','D_S04','D_S07','D_E08']:
    try:
        print('\n### INSIGHT',gid); print(json.dumps(nm.market.get_group_insights(group_id=gid),indent=2,default=str))
    except Exception as e: print('ERR',e)
try:
    print('\n### MARKET'); print(json.dumps(nm.market.get_market_overview(),indent=2,default=str))
except Exception as e: print('ERR',e)
try:
    print('\n### SOCIAL'); print(json.dumps(nm.analytics.get_social_posts(days=14,limit=100),indent=2,default=str))
except Exception as e: print('ERR',e)
try:
    print('\n### RESEARCH'); print(json.dumps(nm.research.list_research_projects(),indent=2,default=str))
except Exception as e: print('ERR',e)
try:
    print('\n### COST'); print(json.dumps(nm.infrastructure.get_cost_info(),indent=2,default=str))
except Exception as e: print('ERR',e)

