import novamind_api as nm, json

def act(label,fn):
 try: print(label,json.dumps(fn(),indent=2,default=str))
 except Exception as e: print(label,'ERROR',repr(e))

# Immediate model upgrades bridge the renewal gap: A2 is inexpensive insurance for the large A base;
# B4 supplies an immediate +~0.46 quality while targeted development keeps building permanent S1 quality.
act('model_tiers',lambda: nm.pricing.set_model_tiers(A=2,B=4,C=4))
act('daily_spend',lambda: nm.marketing.set_daily_spend(operations=80000,development=0))
act('targeted_dev',lambda: nm.analytics.set_targeted_dev_spend(targeted_spend={'S1':50000.0}))
act('social',lambda: nm.marketing.post_social_media(content="You're right—the product isn't an 8/10 if support disappears. We traced a ticket-routing handoff defect and fixed ownership alerts; every currently open ticket is now in today's queue. Reply with your ticket ID and we'll verify the owner and status.",reply_to_post_id=492))

