import novamind_api as nm
q="""SELECT CASE WHEN s.start_day BETWEEN 54 AND 60 THEN 'old54-60' WHEN s.start_day BETWEEN 174 AND 180 THEN 'first174-180' ELSE 'other' END cohort,s.billing_day_mod30,COUNT(*) n,ROUND(SUM(s.effective_price),0) book FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.group_id='S1' AND s.billing_day_mod30 IN (24,25,26,27,28,29,0) GROUP BY cohort,s.billing_day_mod30 ORDER BY cohort,s.billing_day_mod30"""
for r in nm.query(q)['rows']:print(r)

