rows=open('cancel210.txt').read().splitlines()
d={}
for l in rows:
 x=dict(re.findall(r'(\w+)=([^ |]+)',l)); day=int(x['start_day']); plan=x['plan']; n=int(x['n']); d.setdefault(day,{})[plan]=n
# parse orig counts exact from history210
orig={}
for l in open('history210.out'):
 if 'start_day=' in l and 'plan=' in l:
  x=dict(re.findall(r'(\w+)=([^ |]+)',l)); sd=int(x['start_day'])
  if sd in range(174,181) or sd in range(54,61): orig.setdefault(sd,{})[x['plan']]=int(x['conv'])
for day in sorted(d):
 print(day, {p: f"{d[day].get(p,0)}/{orig[day].get(p,0)}={d[day].get(p,0)/orig[day].get(p,1):.1%}" for p in orig[day]})
PY

