import novamind_api as nm
D=224; cash0=6042539.; rows=nm.query("SELECT start_day,billing_day_mod30 mod,SUM(effective_price) book FROM subscriptions WHERE status='subscribed' GROUP BY start_day,billing_day_mod30")['rows']; recent=nm.query("SELECT start_day day,SUM(effective_price) book FROM subscriptions WHERE status='subscribed' AND start_day BETWEEN 218 AND 224 GROUP BY start_day")['rows']; p={r['day']-218:r['book'] for r in recent}; base=sum(r['book'] for r in rows)
def ret(start,age,cl=.7,pre=0,old=.96,mid=.9,rep=.92):
 if age==30:return pre if start<=196 else cl
 if start<=99:return old
 if start<=166:return mid
 return rep
def sim(h,cl=.7,pre=0,old=.96,mid=.9,rep=.92,newdec=.99,cscale=1):
 cash=cash0; ab=base;b={}
 for r in rows:
  delta=(r['mod']-D%30)%30 or 30;b.setdefault(D+delta,[]).append((r['start_day'],r['book']))
 revnew=revrenew=cost=0
 for d in range(225,225+h):
  nb=p[(d-225)%7]*(newdec**((d-225)//7));cash+=nb;ab+=nb;revnew+=nb;b.setdefault(d+30,[]).append((d,nb))
  for s,bk in b.get(d,[]):
   k=bk*ret(s,d-s,cl,pre,old,mid,rep);cash+=k;ab+=k-bk;revrenew+=k;b.setdefault(d+30,[]).append((s,k))
  co=172000+98000*(ab/base)*cscale; cash-=co;cost+=co
 return cash,revnew,revrenew,cost,ab
for cl in [0,.05,.3,.5,.7,.85,.95,1]:
 print('clean',cl)
 for h in [7,28,84,182]:print(h,tuple(round(x) for x in sim(h,cl=cl)))
