import novamind_api as nm,re,collections
posts=nm.analytics.get_social_posts(days=60,limit=2000)['posts']
d=collections.defaultdict(list)
for p in posts:
 txt=p['content']
 m=re.search(r'(?:roughly |about |around |approximately |maybe |estimate(?:d)? (?:at |roughly |about |around )?)([0-9]+\.[0-9]+)\s*(?:quality|improvement|boost|bump)',txt,re.I)
 if not m:m=re.search(r'([0-9]+\.[0-9]+)\s*(?:quality (?:boost|improvement)|quality bump)',txt,re.I)
 if m:d[p['day']].append((float(m.group(1)),p.get('post_id'),txt[:80]))
for day in sorted(d):
 vals=sorted(set(x[0] for x in d[day]))
 print(day,vals,'sum',round(sum(vals),4))
print('sums post 197:',sum(sum(set(x[0] for x in d[day])) for day in d if day>=197))

