def rrate(s,age,sc):
 # current survivors by start bands have very different observed later-cycle durability
 v={
 'bear': dict(first=0,a=.80,b=.65,c=.55,d=.70,e=.50),
 'low': dict(first=0,a=.90,b=.80,c=.70,d=.80,e=.65),
 'base':dict(first=0,a=.96,b=.90,c=.82,d=.88,e=.80),
 'up':dict(first=.25,a=.985,b=.96,c=.92,d=.95,e=.92),
 'high':dict(first=.7,a=.997,b=.99,c=.98,d=.99,e=.98),
 }[sc]
 if age==30:return v['first']
 if s<=60:return v['a']
 if s<=82:return v['b']
 if s<=112:return v['c']
 if s<=138:return v['d']
 return v['e']
def sim(h,sc):
 k={
 'bear':dict(nd=.82,cv=.35,cs=1.1), 'low':dict(nd=.90,cv=.60,cs=1.05),
 'base':dict(nd=.97,cv=.82,cs=1), 'up':dict(nd=1,cv=1,cs=1.05),
 'high':dict(nd=1.02,cv=1.10,cs=1.1)}[sc]
 c=cash0;ab=base;b={}
 for r in rows:b.setdefault(D+((r['mod']-D%30)%30 or 30),[]).append((r['start_day'],r['book']))
 for d in range(232,232+h):
  wk=(d-232)//7;nb=p[(d-232)%7]*k['nd']**wk*k['cv'];c+=nb;ab+=nb;b.setdefault(d+30,[]).append((d,nb))
  for s,bk in b.get(d,[]):
   rt=rrate(s,d-s,sc);z=bk*rt;c+=z;ab+=z-bk;b.setdefault(d+30,[]).append((s,z))
  c-=70000+15000*(ab/base)*k['cs']+2000*k['nd']**wk
 return c,ab
for h in [7,28,84,182]: print(h,{s:tuple(round(z) for z in sim(h,s)) for s in ['bear','low','base','up','high']})

