import novamind_api as nm, json

# Cash-harvest adjustment: at A1/B2 the Day232-238 cohorts still produced
# $345.8k immediate cash receipts on $114.2k compute, but B=$59 now captures
# nearly every converter while conversion has settled around 22%. Lower B to
# $49 for a one-week elasticity test: even modest volume lift can raise
# revenue/lead, while one-month LTV means no ongoing discount is promised.
print('prices', json.dumps(nm.pricing.set_prices(A=20, B=49, C=149), indent=2))

# Keep low model tiers and zero development: Days202-208 again cancelled 100%
# at first renewal despite having enrolled under A2/B4 and massive S1 dev.
print('tiers', json.dumps(nm.pricing.set_model_tiers(A=1, B=2, C=4), indent=2))
print('target_dev', json.dumps(nm.analytics.set_targeted_dev_spend(targeted_spend={}), indent=2))
print('ads', json.dumps(nm.marketing.set_targeted_ad_spend(targeted_spend={}), indent=2))

# Global ops $60k keeps all active-account issues age zero. Clear any targeted
# extras and retain it this week while testing price, to avoid confounding.
print('spend', json.dumps(nm.marketing.set_daily_spend(operations=60000, development=0), indent=2))
# Installed client exposes the legacy per-group alias only.
print('target_ops', json.dumps(nm.analytics.set_targeted_ops_spend(targeted_spend={}), indent=2))

# 14.9m recent peak fits T5. No promotion or in-app ads.
print('capacity', json.dumps(nm.infrastructure.set_capacity_tier(tier=5), indent=2))

# Today's customer feedback says both quality and support remain visibly weak.
# Be candid; do not repeat unsupported same-day/fix-shipped promises.
msg=("We hear two clear failures: support updates aren't reaching people, and recent output quality is uneven. "
     "We won't call that fixed. This week we're publishing ticket-owner changes plus before/after workflow examples, "
     "then reporting what still fails.")
print('chars', len(msg))
print('social', json.dumps(nm.marketing.post_social_media(content=msg, reply_to_post_id=636), indent=2))

