import novamind_api as nm, json

def show(label, fn):
    try:
        r=fn(); print(label, json.dumps(r, indent=2))
    except Exception as e:
        print(label, 'ERROR', repr(e))

# End the one-week quality pulses now that S1 has a large cushion and D_E02 has cleared its noisy zero-price floor.
show('spend', lambda: nm.marketing.set_daily_spend(operations=70000, development=0))
show('targeted_ops', lambda: nm.analytics.set_targeted_ops_spend(by_group={'S1':5000.0}, by_plan={}, by_group_plan={}, by_customer={}))
show('targeted_dev', lambda: nm.analytics.set_targeted_dev_spend(targeted_spend={}))
# Small monetization test against S1's new quality cushion; reassess ad revenue and renewal churn next week.
show('ads_strength', lambda: nm.marketing.set_ads_strength(global_strength=0.0, by_group={'S1':0.1}, by_customer={}))
