    x[2]*=z; x[3]*=z; x[4]+=30; x[5]+=1; renew+=x[3]
  activepre=sum(x[2] for x in b)
  scale=(activepre/active0)**.9*SC[sc]['leaddec']**week
  leads=leadpat[day%7]*scale
  rpl=max(1,SC[sc]['rev0']-SC[sc]['drop']*week)
  book=leads*rpl; conv=min(.75,rpl/39); n=leads*conv
  b.append([day,'B',n,book,day+30,0])
  active=sum(x[2] for x in b)
  ops=max(500,60000*(active/active0))*SC[sc]['ops']
  compute=sum(x[2]*usagepat[day%7]*{'A':.0003,'B':.002,'C':.012}[x[1]] for x in b)
  usage=active*usagepat[day%7]
  cap=4000 if usage<7_200_000 else 10000
  cost=ops+compute+cap+.5*leads*other_ratio
  cash+=renew+book-cost
  out.append((day,cash,renew,book,cost,active,leads,rpl))
