import novamind_api as nm
sql="""SELECT l.day, -SUM(l.amount)*2 all_leads, COUNT(s.subscription_id) evaluated, SUM(CASE WHEN s.status<>'lost' THEN 1 ELSE 0 END) conv, SUM(CASE WHEN s.status<>'lost' THEN s.effective_price ELSE 0 END) initbook FROM ledger l LEFT JOIN subscriptions s ON s.start_day=l.day LEFT JOIN customers c ON c.customer_id=s.customer_id AND c.customer_type='small' WHERE l.category='lead_acquisition_cost' AND l.day BETWEEN 224 AND 273 GROUP BY l.day ORDER BY l.day"""
# above cartesian invalid sums repeated. separate fetch
lr={x['day']:-2*x['amt'] for x in nm.query("SELECT day,SUM(amount) amt FROM ledger WHERE category='lead_acquisition_cost' AND day BETWEEN 224 AND 273 GROUP BY day")['rows']}
sr={x['start_day']:x for x in nm.query("SELECT s.start_day,COUNT(*) evaluated,SUM(CASE WHEN s.status<>'lost' THEN 1 ELSE 0 END) conv,SUM(CASE WHEN s.status<>'lost' THEN s.effective_price ELSE 0 END) initbook FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='small' AND s.start_day BETWEEN 224 AND 273 GROUP BY s.start_day")['rows']}
for d in range(224,274):
 x=sr.get(d,{}); leads=lr.get(d,0); book=x.get('initbook',0); conv=x.get('conv',0)
 print(d,'leads',leads,'eval',x.get('evaluated',0),'conv',conv,'rate',round(conv/leads,4) if leads else 0,'book',book,'$/lead',round(book/leads,2) if leads else 0,'avg',round(book/conv,2) if conv else 0)

