import novamind_api as nm
rev={r['day']:r['rev'] for r in nm.query("SELECT day,SUM(amount) rev FROM ledger WHERE category='subscription_payment' GROUP BY day")['rows']}
init={r['start_day']:r['book'] for r in nm.query("SELECT start_day,SUM(CASE WHEN status<>'lost' THEN effective_price*seat_count ELSE 0 END) book FROM subscriptions GROUP BY start_day")['rows']}
old={d:rev.get(d,0)-init.get(d,0) for d in rev}
for d in range(180,274):
 if d in old:
  ratio=old[d]/old.get(d-30,1) if old.get(d-30,0)>0 else 0
  print(d,'rev',round(rev[d]),'init',round(init.get(d,0)),'old',round(old[d]),'prev',round(old.get(d-30,0)),'ratio',round(ratio,4))

