import novamind_api as nm
r=nm.query("""SELECT ((s.billing_day_mod30-10+30)%30) ahead,s.plan,COUNT(*) n,SUM(s.effective_price) book FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.group_id='S1' AND s.start_day<=139 GROUP BY ahead,s.plan ORDER BY ahead,s.plan""")
for x in r['rows']: print('ACTIVE',x)
r=nm.query("""SELECT end_day-250 ahead,plan,COUNT(*) n,SUM(effective_price) book FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND c.group_id='S1' AND s.start_day<=139 AND end_day BETWEEN 251 AND 280 GROUP BY ahead,plan ORDER BY ahead,plan""")
for x in r['rows']: print('CANCEL',x)

