import novamind_api as nm
cash0=10140285.; curday=287
rows=nm.query("""SELECT s.customer_id,s.billing_day_mod30,s.effective_price,s.plan,s.start_day FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.group_id='S1' AND s.start_day<=139""")['rows']
# query limit 5k! aggregate into plan buckets instead.
agg=nm.query("""SELECT ((s.billing_day_mod30-17+30)%30) ahead,s.plan,SUM(s.effective_price) book,COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.group_id='S1' AND s.start_day<=139 GROUP BY ahead,s.plan ORDER BY ahead,s.plan""")['rows']
book={(int(r['ahead']),r['plan']):float(r['book']) for r in agg}; cnt={(int(r['ahead']),r['plan']):float(r['n']) for r in agg}
for d in range(30):
 for p in 'ABC':book.setdefault((d,p),0);cnt.setdefault((d,p),0)
n0=sum(cnt.values()); extra0=1931

def capcost(u):return 4000 if u>2.5e6 else (1330 if u>8e5 else (530 if u>2e5 else 215))
def sim(sB=.965,sA=.2,sC=.95,days=182,firstB=None,firstA=None):
 b=dict(book);n=dict(cnt);cash=cash0;out=[]
 for d in range(1,days+1):
  k=d%30; rec=0
  for p,s in [('A',sA),('B',sB),('C',sC)]:
   if firstB and d<=7 and p=='B':s=firstB
   if firstA is not None and d<=7 and p=='A':s=firstA
   rec+=b[k,p]*s;b[k,p]*=s;n[k,p]*=s
  extra=extra0*max(0,1-d/18)
  act=sum(n.values())+extra
  # Maintain ops current week; weekly proportional after. B4 compute proportional to plan composition from current observed weekday per-user usage.
  ops=35000 if d<=7 else max(500,35000*act/(n0+extra0))
  # current weighted weekday tokens/customer ~85; compute B4 .012 = $1.02/account/day
  comp=1.02*(sum(n[k,p] for k in range(30) for p in ('B','C'))) + .026*sum(n[k,'A'] for k in range(30))
  usage=85*act
  cost=ops+capcost(usage)+comp+30
  cash+=rec-cost
  if d in (7,28,84,182): out.append((d,round(cash),round(sum(b.values())),round(act),round(rec),round(cost)))
 return out
for sb in (.8,.85,.9,.93,.95,.965,.98,.99):print(sb,sim(sb,firstB=.97,firstA=.15))

