import novamind_api as nm

def q(name,sql):
 print('\n##',name)
 try:
  for r in nm.query(sql)['rows']: print(r)
 except Exception as e: print('ERR',e)

q('daily ledger',"""SELECT day, category, ROUND(SUM(amount),2) amount FROM ledger WHERE day BETWEEN 256 AND 315 GROUP BY day,category ORDER BY day,category""")
q('active due book all cohorts',"""SELECT billing_day_mod30,CASE WHEN start_day<=139 THEN 'mature' WHEN start_day<288 THEN 'mid' ELSE 'new288+' END cohort,plan,effective_price,COUNT(*) n,ROUND(SUM(effective_price*seat_count),2) book FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30,cohort,plan,effective_price ORDER BY billing_day_mod30,cohort,plan,effective_price""")
q('cancel daily cohort',"""SELECT end_day,CASE WHEN start_day<=139 THEN 'mature' WHEN start_day<288 THEN 'mid' ELSE 'new288+' END cohort,plan,effective_price,COUNT(*) n,ROUND(SUM(effective_price*seat_count),2) book FROM subscriptions WHERE status='cancelled' AND end_day BETWEEN 256 AND 315 GROUP BY end_day,cohort,plan,effective_price ORDER BY end_day,cohort,plan,effective_price""")
q('starts daily',"""SELECT start_day,status,plan,effective_price,COUNT(*) n,ROUND(SUM(effective_price),2) book FROM subscriptions WHERE start_day BETWEEN 286 AND 315 GROUP BY start_day,status,plan,effective_price ORDER BY start_day,status,plan,effective_price""")
q('active by start month',"""SELECT CASE WHEN start_day<=49 THEN '<=49' WHEN start_day<=79 THEN '50-79' WHEN start_day<=109 THEN '80-109' WHEN start_day<=139 THEN '110-139' WHEN start_day<288 THEN '140-287' ELSE '288+' END coh,COUNT(*) n,ROUND(SUM(effective_price),2) book FROM subscriptions WHERE status='subscribed' GROUP BY coh ORDER BY MIN(start_day)""")
q('research',"SELECT * FROM research_projects ORDER BY started_day")
q('cash',"SELECT ROUND(SUM(amount),2) cash FROM ledger")

