import novamind_api as nm
qs={
'week bucket cash':"""SELECT SUM(CASE WHEN billing_day_mod30 IN (16,17,18,19,20,21,22) THEN effective_price ELSE 0 END) book,COUNT(CASE WHEN billing_day_mod30 IN (16,17,18,19,20,21,22) THEN 1 END) n FROM subscriptions WHERE status='subscribed'""",
'downgrade week details':"""SELECT s.end_day,s.start_day,s.status,s.plan,s.pending_plan,s.effective_price,COUNT(*) n FROM subscriptions s WHERE s.end_day BETWEEN 309 AND 315 OR (s.status='subscribed' AND s.pending_plan IS NOT NULL) GROUP BY s.end_day,s.start_day,s.status,s.plan,s.pending_plan,s.effective_price ORDER BY s.end_day""",
'ledger past cycles':"""SELECT CASE WHEN day BETWEEN 256 AND 285 THEN '256-285' WHEN day BETWEEN 286 AND 315 THEN '286-315' END p,category,SUM(amount) amt FROM ledger WHERE day BETWEEN 256 AND 315 GROUP BY p,category ORDER BY p,category""",
'week retained counts exact buckets':"""SELECT billing_day_mod30,COUNT(*) active,SUM(effective_price) book,(SELECT COUNT(*) FROM subscriptions x WHERE x.status='cancelled' AND x.start_day<=139 AND x.end_day=CASE WHEN s.billing_day_mod30 BETWEEN 16 AND 22 THEN 300+s.billing_day_mod30 ELSE 0 END) canc FROM subscriptions s WHERE status='subscribed' AND start_day<=139 AND billing_day_mod30 BETWEEN 16 AND 22 GROUP BY billing_day_mod30 ORDER BY billing_day_mod30"""
}
for n,q in qs.items():
 print('\n',n)
 try:
  for x in nm.query(q)['rows']:print(x)
 except Exception as e:print(e)

