import novamind_api as nm
R=lambda q:nm.query(q)['rows']; now=350;cash=R('SELECT SUM(amount) cash FROM ledger')[0]['cash']
a={(int(r['start_day']),int(r['billing_day_mod30']),r['plan'],float(r['effective_price'])):float(r['n']) for r in R("SELECT start_day,billing_day_mod30,plan,effective_price,COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY start_day,billing_day_mod30,plan,effective_price")}
lead=3663/290; cpu=317237.34/7/45713
# Latest observed cancellation hazard by exact start cohorts 43-139; interpolated remaining future legacy uses B59 base 6% under central.
# Evidence says cohorts 48-50 have a shock; likely because their prior subscription experience. 51+ historically retained better.
obs={43:.0504,44:.061,45:.0631,46:.0591,47:.1201,48:.3638,49:.5414,50:.4779}
def hz(st,p,pr,scale):
 if st>139:return 1
 if pr==49:return min(.95,.12*scale)
 if st in obs:return min(.95,obs[st]*scale)
 if p=='B':return min(.95,.06*scale)
 return min(.99,.6*scale)
def sim(h,signup=40,scale=1,ops=15000,research=.15,growth=-.005,comp=1):
 aa=dict(a);c=cash
 for d in range(351,351+h):
  rev=0
  for k,n in list(aa.items()):
   st,m,p,pr=k
   if d%30==m:
    x=hz(st,p,pr,scale)*(1-research if d>=458 else 1);n*=1-x;aa[k]=n;rev+=n*pr
  s=max(0,signup*(1+growth)**((d-351)/7));aa[(d,d%30,'B',59.)]=s;rev+=s*59
  acct=sum(aa.values());c+=rev-acct*cpu*comp-4000-ops-.5*lead*s
 return c
for lab,kw in [('sev',dict(signup=20,scale=2.5,ops=20000,research=0,growth=-.03,comp=1.08)),('down',dict(signup=25,scale=1.7,ops=18000,research=.05,growth=-.02,comp=1.05)),('weak',dict(signup=32,scale=1.3,ops=15000,research=.1,growth=-.01,comp=1.02)),('cen',dict()),('strong',dict(signup=50,scale=.8,ops=12000,research=.25,growth=0,comp=.97)),('up',dict(signup=60,scale=.6,ops=10000,research=.35,growth=.005,comp=.95))]:print(lab,[round(sim(h,**kw)) for h in (7,28,84,147,182)])
