cat > cohort_compare357.py <<'PY'
import novamind_api as nm
R=lambda q:nm.query(q)['rows']
for cyc in [(288,317),(318,347),(328,357)]:
 a,b=cyc
 print('\ncycle',cyc)
 q=f'''SELECT end_day,plan,effective_price,COUNT(*) canc FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND status='cancelled' AND start_day<=139 AND end_day BETWEEN {a} AND {b} GROUP BY end_day,plan,effective_price ORDER BY end_day,plan,effective_price'''
 # receipt + cancelled book approximates pre-due by day and plan. Note receipt rows for survivors.
 canc={(r['end_day'],r['plan'],float(r['effective_price'])):r['canc'] for r in R(q)}
 pay={(r['day'],r['plan'],float(r['effective_price'])):r['n'] for r in R(f'''SELECT l.day,s.plan,s.effective_price,COUNT(*) n FROM ledger l JOIN subscriptions s ON CAST(substr(l.note,instr(l.note,'customer ')+9) AS INTEGER)=s.customer_id WHERE l.category='subscription_payment' AND l.day BETWEEN {a} AND {b} AND s.start_day<=139 GROUP BY l.day,s.plan,s.effective_price''')}
 for d in range(a,b+1):
  out=[]
  for p,pr in [('A',16.),('A',20.),('B',49.),('B',59.)]:
   c=canc.get((d,p,pr),0); n=pay.get((d,p,pr),0); den=n+c
   if den: out.append(f'{p}{int(pr)} {n}/{den}={n/den:.1%}')
  print(d,'; '.join(out))
print('\nfuture active prebook')
for r in R("SELECT ((billing_day_mod30-(357%30)+30)%30) ahead,plan,effective_price,COUNT(*) n,SUM(effective_price) book FROM subscriptions WHERE status='subscribed' AND start_day<=139 GROUP BY ahead,plan,effective_price ORDER BY ahead,plan,effective_price"): print(r)
PY
./novamind-operation python cohort_compare357.py > cohort_compare357.out; sed -n '1,360p' cohort_compare357.out

