cat > currentstats357.py <<'PY'
import novamind_api as nm
qs={
'by_start_summary':"""SELECT CASE WHEN start_day<43 THEN 'pre43' WHEN start_day<=57 THEN '43-57 cliffed' WHEN start_day<=67 THEN '58-67 due_next' WHEN start_day<=77 THEN '68-77' WHEN start_day<=87 THEN '78-87' WHEN start_day<=117 THEN '88-117' WHEN start_day<=139 THEN '118-139' ELSE 'recent' END band,plan,effective_price,COUNT(*) n,SUM(effective_price) book FROM subscriptions WHERE status='subscribed' GROUP BY band,plan,effective_price ORDER BY band,plan,effective_price""",
'cancels_by_day_all':"SELECT end_day,COUNT(*) n FROM subscriptions WHERE status='cancelled' AND end_day>=328 GROUP BY end_day ORDER BY end_day",
'resolution_type':"SELECT resolution_type,COUNT(*) n FROM issues WHERE status='open' AND EXISTS(SELECT 1 FROM subscriptions s WHERE s.customer_id=issues.customer_id AND s.status='subscribed') GROUP BY resolution_type",
'enterprise_latest':"SELECT * FROM enterprise_turns WHERE day>=330 ORDER BY day,message_id",
'ledger today cats':"SELECT day,category,SUM(amount) amt FROM ledger WHERE day>=351 GROUP BY day,category ORDER BY day,category",
'usage cost per act':"SELECT sd.day,sd.total_usage_units,(SELECT COUNT(*) FROM subscriptions s WHERE s.status='subscribed' AND s.start_day<=sd.day AND (s.end_day IS NULL OR s.end_day>sd.day)) n FROM service_day sd WHERE sd.day>=328 ORDER BY sd.day"
}
for k,q in qs.items():
 print('\n##',k)
 try:
  for r in nm.query(q)['rows']:print(r)
 except Exception as e:print('ERR',e)
PY
./novamind-operation python currentstats357.py > currentstats357.out; cat currentstats357.out

