arguments.content:
import novamind_api as nm

def q(name,sql):
 print('\n##',name)
 try:
  for x in nm.query(sql)['rows']: print(x)
 except Exception as e: print('ERR',e)

q('age270 outcomes starts78-94',"""SELECT start_day,effective_price,status,COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND start_day BETWEEN 78 AND 94 GROUP BY start_day,effective_price,status ORDER BY start_day,effective_price,status""")
q('age240 outcomes starts108-124',"""SELECT start_day,effective_price,status,COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND start_day BETWEEN 108 AND 124 GROUP BY start_day,effective_price,status ORDER BY start_day,effective_price,status""")
q('last payment each currently active sample aggregate',"""SELECT s.start_day,s.effective_price,COUNT(*) n,SUM(s.effective_price) book FROM subscriptions s WHERE s.status='subscribed' AND s.start_day<=139 GROUP BY s.start_day,s.effective_price ORDER BY s.start_day,s.effective_price""")
q('historical existing promo test timing',"SELECT day,settings_json FROM config_overrides WHERE setting_type='promotion' ORDER BY day")
q('price changes',"SELECT day,price_A,price_B,price_C FROM config_history ORDER BY day")

