import novamind_api as nm

def q(name,sql):
 print('\n##',name)
 try:
  for x in nm.query(sql)['rows']: print(x)
 except Exception as e: print('ERR',e)
# ledger note links subscription current final price, so subscriptions that later change may confound historical effective
q('payments 235-275 direct',"""SELECT day,COUNT(*) n,SUM(amount) amt FROM ledger WHERE category='subscription_payment' AND day BETWEEN 235 AND 275 GROUP BY day ORDER BY day""")
q('starts59-65 prior cycle cancels exact',"""SELECT end_day,start_day,effective_price,COUNT(*) n FROM subscriptions WHERE status='cancelled' AND start_day BETWEEN 59 AND 65 AND end_day BETWEEN 250 AND 335 GROUP BY end_day,start_day,effective_price ORDER BY end_day,start_day,effective_price""")
q('current listed effective',"SELECT listed_price,effective_price,COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY listed_price,effective_price")

