'ledger30':'''SELECT category,SUM(amount) amount,COUNT(*) n FROM ledger WHERE day>=342 AND day<372 GROUP BY category ORDER BY category''',
'cancel_ages_30':'''SELECT end_day-start_day age,COUNT(*) n,SUM(effective_price) prices FROM subscriptions WHERE end_day>=342 AND end_day<372 GROUP BY age ORDER BY age''',
'subs_end_daily_age':'''SELECT end_day, end_day-start_day age,COUNT(*) n FROM subscriptions WHERE end_day>=342 AND end_day<372 GROUP BY end_day,age ORDER BY end_day,age'''
}
