import novamind_api as nm

def q(name,sql):
 print('\n##',name)
 try:
  r=nm.query(sql)
  for x in r['rows']: print(x)
  if r.get('warning'): print('WARNING',r['warning'])
 except Exception as e: print('ERR',e)

q('cash and ledger week/category',"SELECT category,ROUND(SUM(amount),2) amt,COUNT(*) entries FROM ledger WHERE day BETWEEN 358 AND 364 GROUP BY category ORDER BY amt DESC")
q('ledger daily',"SELECT day,ROUND(SUM(CASE WHEN amount>0 THEN amount ELSE 0 END),2) receipts,ROUND(SUM(CASE WHEN amount<0 THEN -amount ELSE 0 END),2) costs,ROUND(SUM(amount),2) net FROM ledger WHERE day BETWEEN 351 AND 364 GROUP BY day ORDER BY day")
q('payments daily plan/price',"SELECT l.day,s.plan,s.effective_price,COUNT(*) payments,ROUND(SUM(l.amount),2) amt FROM ledger l JOIN subscriptions s ON CAST(substr(l.note,instr(l.note,'customer ')+9) AS INTEGER)=s.customer_id WHERE l.category='subscription_payment' AND l.day BETWEEN 358 AND 364 GROUP BY l.day,s.plan,s.effective_price ORDER BY l.day,s.plan,s.effective_price")
q('service days',"SELECT * FROM service_day WHERE day BETWEEN 351 AND 364 ORDER BY day")
q('issue daily total flow',"""SELECT d.day,
(SELECT COUNT(*) FROM issues i WHERE i.open_day=d.day) opened,
(SELECT COUNT(*) FROM issues i WHERE i.resolved_day=d.day) resolved,
(SELECT COUNT(*) FROM issues i WHERE i.open_day<=d.day AND (i.resolved_day IS NULL OR i.resolved_day>d.day)) endopen,
(SELECT COUNT(*) FROM issues i WHERE i.open_day<=d.day AND (i.resolved_day IS NULL OR i.resolved_day>d.day) AND EXISTS(SELECT 1 FROM subscriptions s WHERE s.customer_id=i.customer_id AND s.status='subscribed')) activeacct_endopen
FROM service_day d WHERE d.day BETWEEN 351 AND 364 ORDER BY d.day""")
q('open issue age current active account',"""SELECT i.open_day,i.days_open,COUNT(*) n FROM issues i WHERE i.status='open' AND EXISTS(SELECT 1 FROM subscriptions s WHERE s.customer_id=i.customer_id AND s.status='subscribed') GROUP BY i.open_day,i.days_open ORDER BY i.open_day""")
q('open issue age current inactive account',"""SELECT CASE WHEN i.open_day<307 THEN 'old' ELSE CAST(i.open_day AS TEXT) END openday, i.days_open,COUNT(*) n FROM issues i WHERE i.status='open' AND NOT EXISTS(SELECT 1 FROM subscriptions s WHERE s.customer_id=i.customer_id AND s.status='subscribed') GROUP BY openday,i.days_open ORDER BY i.days_open DESC LIMIT 40""")
q('issue recent fate',"""SELECT i.open_day,COUNT(*) n,SUM(CASE WHEN i.status='open' THEN 1 ELSE 0 END) stillopen,AVG(CASE WHEN i.resolved_day IS NOT NULL THEN i.resolved_day-i.open_day END) avgdays,MAX(CASE WHEN i.resolved_day IS NOT NULL THEN i.resolved_day-i.open_day END) maxdays FROM issues i WHERE i.open_day BETWEEN 351 AND 364 GROUP BY i.open_day ORDER BY i.open_day""")
q('active composition',"""SELECT c.group_id,s.plan,s.effective_price,COUNT(*) n,SUM(s.effective_price) book,AVG(s.start_day) avgstart FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id,s.plan,s.effective_price ORDER BY c.group_id,s.plan,s.effective_price""")
q('active by cohort band',"""SELECT CASE WHEN s.start_day<=139 THEN 'mature' WHEN s.start_day<278 THEN 'mid' WHEN s.start_day<307 THEN 'recent_renewed' ELSE 'new_unrenewed' END cohort,s.plan,s.effective_price,COUNT(*) n,SUM(s.effective_price) book FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.status='subscribed' GROUP BY cohort,s.plan,s.effective_price ORDER BY cohort,s.plan,s.effective_price""")
q('cancels daily cohort plan',"""SELECT s.end_day,CASE WHEN s.start_day<=139 THEN 'mature' WHEN s.start_day<278 THEN 'mid' ELSE 'new' END cohort,s.plan,s.effective_price,COUNT(*) n,SUM(s.effective_price) book FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.status='cancelled' AND s.end_day BETWEEN 351 AND 364 GROUP BY s.end_day,cohort,s.plan,s.effective_price ORDER BY s.end_day,cohort,s.plan,s.effective_price""")
q('cancels exact start this week',"""SELECT s.end_day,s.start_day,s.plan,s.effective_price,COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.status='cancelled' AND s.end_day BETWEEN 358 AND 364 GROUP BY s.end_day,s.start_day,s.plan,s.effective_price ORDER BY s.end_day,s.start_day""")
q('first renewal outcomes cohorts 288-306',"""SELECT s.start_day,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) cancelled,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,COUNT(*) total FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.start_day BETWEEN 302 AND 320 GROUP BY s.start_day ORDER BY s.start_day""")
q('mature current buckets',"""SELECT s.billing_day_mod30,s.plan,s.effective_price,COUNT(*) active,SUM(s.effective_price) book FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.status='subscribed' AND s.start_day<=139 GROUP BY s.billing_day_mod30,s.plan,s.effective_price ORDER BY s.billing_day_mod30,s.plan,s.effective_price""")
q('mature cancellation cycle last 37d',"""SELECT s.end_day,s.plan,s.effective_price,COUNT(*) canc FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.status='cancelled' AND s.start_day<=139 AND s.end_day BETWEEN 314 AND 364 GROUP BY s.end_day,s.plan,s.effective_price ORDER BY s.end_day,s.plan""")
q('recent leads conversion by day',"""SELECT c.created_day,COUNT(*) leads,SUM(CASE WHEN s.status!='lost' THEN 1 ELSE 0 END) converted,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) nowactive,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) canceled FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.customer_type='small' AND c.created_day BETWEEN 351 AND 364 GROUP BY c.created_day ORDER BY c.created_day""")
q('acquisition sources this week',"""SELECT c.acquisition_source,COUNT(*) leads,SUM(CASE WHEN s.status!='lost' THEN 1 ELSE 0 END) converted FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.customer_type='small' AND c.created_day BETWEEN 358 AND 364 GROUP BY c.acquisition_source""")
q('social',"SELECT post_id,day,content FROM social_media_posts WHERE day BETWEEN 351 AND 364 ORDER BY day,post_id")
q('fresh enterprise',"SELECT * FROM enterprise_turns WHERE day BETWEEN 351 AND 364 ORDER BY day,message_id")
q('notifications',"SELECT * FROM notifications WHERE day BETWEEN 351 AND 364 ORDER BY day,notification_id")
q('research',"SELECT * FROM research_projects ORDER BY start_day")
q('config recent',"SELECT * FROM config_history WHERE day>=351 ORDER BY day")
q('overrides recent',"SELECT * FROM config_overrides WHERE day>=351 ORDER BY id")
q('cash',"SELECT SUM(amount) cash FROM ledger")
q('future due all active',"""SELECT ((s.billing_day_mod30-(364%30)+30)%30) daysahead,s.plan,s.effective_price,COUNT(*) n,SUM(s.effective_price) book FROM subscriptions s WHERE s.status='subscribed' GROUP BY daysahead,s.plan,s.effective_price ORDER BY daysahead,s.plan""")
q('future due mature active',"""SELECT ((s.billing_day_mod30-(364%30)+30)%30) daysahead,s.plan,s.effective_price,COUNT(*) n,SUM(s.effective_price) book FROM subscriptions s WHERE s.status='subscribed' AND s.start_day<=139 GROUP BY daysahead,s.plan,s.effective_price ORDER BY daysahead,s.plan""")
q('new current issue incidence by start day',"""SELECT s.start_day,COUNT(DISTINCT s.customer_id) active,COUNT(i.issue_id) total_issues,SUM(CASE WHEN i.status='open' THEN 1 ELSE 0 END) openissues FROM subscriptions s LEFT JOIN issues i ON i.customer_id=s.customer_id WHERE s.status='subscribed' AND s.start_day>=300 GROUP BY s.start_day ORDER BY s.start_day""")
q('macro',"SELECT * FROM macroeconomic_conditions ORDER BY day DESC LIMIT 6")
q('prior forecasts due',"SELECT * FROM predictions WHERE submit_day>=315 ORDER BY submit_day,horizon_days")
