import novamind_api as nm, json
out={}
# Preserve the strongest economically viable serving tier. B4 still leaves a severe
# age-300 cliff, but B5's 10% quality gain costs 2.5x per token and cannot repay from
# the roughly $320k due book this week; a downgrade would put even that renewal cash
# at risk. Keep quotas and one more week of T4 because Day365 usage is near T3's cap.
out['prices']=nm.pricing.set_prices(A=20,B=59,C=149)
out['tiers']=nm.pricing.set_model_tiers(A=2,B=4,C=4)
out['quotas']=nm.pricing.set_usage_quotas(A=300,B=1000,C=1000)
out['capacity']=nm.infrastructure.set_capacity_tier(tier=4)
# At $15k/day every issue on a currently active account still clears by the next day;
# current inflow (~3.7k/day) is close to observed throughput, so cutting this week
# would create aged tickets despite the shrinking book.
out['spend']=nm.marketing.set_daily_spend(operations=15000,development=0)
out['target_ops']=nm.analytics.set_targeted_ops_spend(targeted_spend={})
out['target_dev']=nm.analytics.set_targeted_dev_spend(targeted_spend={})
# Acquisition is now ~1.6 starts/day and every recent cohort still fails first renewal.
# Avoid paid CAC, discounts, and quality-degrading in-app ads.
out['ads']=nm.marketing.set_targeted_ad_spend(targeted_spend={})
out['ads_strength']=nm.marketing.set_ads_strength(global_strength=0.0,by_group={},by_customer={})
out['lead_promo']=nm.marketing.set_lead_promotion(global_promotion=0.0,by_group={'S1':0.0,'S2':0.0,'S3':0.0,'E1':0.0,'E2':0.0,'E3':0.0},by_channel={},by_channel_group={})
out['promotion']=nm.pricing.set_promotion(global_promotion=0.0,by_group={'S1':0.0,'S2':0.0,'S3':0.0,'E1':0.0,'E2':0.0,'E3':0.0},by_customer={},by_group_plan={})
# Address the sole fresh product-quality complaint with a specific diagnostic request,
# rather than repeating an unverifiable blanket support SLA.
msg=("Generic output that forces a full rewrite isn't acceptable. Share the failed brief plus one example of the tone you expected. "
     "One owner will review both, explain what regressed, and give you a concrete next step; we'll inspect that session's latency too.")
out['social_chars']=len(msg)
out['social']=nm.marketing.post_social_media(content=msg,reply_to_post_id=1032)
for k,v in out.items(): print(k,json.dumps(v,indent=2) if isinstance(v,(dict,list)) else v)
