import novamind_api as nm, json
out={}
# Preserve the strongest available model and quality stock. The current mature-book
# cliff is broad (roughly 42-59% billing survival for ten consecutive days), so a
# tier reduction would be destructive; B5's +10% quality is too small for 2.5x cost.
out['prices']=nm.pricing.set_prices(A=20,B=59,C=149)
out['tiers']=nm.pricing.set_model_tiers(A=2,B=4,C=4)
out['quotas']=nm.pricing.set_usage_quotas(A=300,B=1000,C=1000)
out['capacity']=nm.infrastructure.set_capacity_tier(tier=4)
# $15k/day leaves no active-account ticket older than today: the dashboard's 4,396
# are all Day357 arrivals. Keep this proven minimum rather than restoring $25k;
# excess resolutions cannot repair the old inactive-account orphan queue.
out['spend']=nm.marketing.set_daily_spend(operations=15000,development=0)
out['target_ops']=nm.analytics.set_targeted_ops_spend(targeted_spend={})
out['target_dev']=nm.analytics.set_targeted_dev_spend(targeted_spend={})
# Recent users still cancel 100% at first renewal and current organic starts are
# only ~11/day. Do not pay CAC or dilute initial cash while LTV remains broken.
out['ads']=nm.marketing.set_targeted_ad_spend(targeted_spend={})
out['ads_strength']=nm.marketing.set_ads_strength(global_strength=0.0,by_group={},by_customer={})
out['lead_promo']=nm.marketing.set_lead_promotion(global_promotion=0.0,by_group={'S1':0.0,'S2':0.0,'S3':0.0,'E1':0.0,'E2':0.0,'E3':0.0},by_channel={},by_channel_group={})
out['promotion']=nm.pricing.set_promotion(global_promotion=0.0,by_group={'S1':0.0,'S2':0.0,'S3':0.0,'E1':0.0,'E2':0.0,'E3':0.0},by_customer={},by_group_plan={})
# Today's public complaints specifically contradict handoff ownership. Acknowledge
# that gap without claiming backend ticket age equals customer-visible support.
msg=("You're right: being bounced between teams is not one-owner support. I'm tracing this handoff failure now. "
     "Reply with the ticket ID; one accountable owner will confirm the next action and timing—without making you restart the story.")
out['social_chars']=len(msg)
out['social']=nm.marketing.post_social_media(content=msg,reply_to_post_id=997)
for k,v in out.items(): print(k,json.dumps(v,indent=2) if isinstance(v,(dict,list)) else v)

