import novamind_api as nm
for sql in [
"SELECT * FROM config_history WHERE day BETWEEN 35 AND 80 ORDER BY day",
"SELECT day,category,SUM(amount) amt,COUNT(*) n FROM ledger WHERE day BETWEEN 35 AND 80 GROUP BY day,category ORDER BY day,category",
"SELECT start_day,COUNT(*) n,AVG(customer_id) avgid FROM subscriptions WHERE status='subscribed' AND start_day BETWEEN 43 AND 58 GROUP BY start_day ORDER BY start_day",
"SELECT end_day-start_day age,start_day,COUNT(*) n FROM subscriptions WHERE start_day BETWEEN 43 AND 58 AND plan='B' AND effective_price=59 AND status='cancelled' GROUP BY start_day,age ORDER BY start_day,age"
]:
 print('\nSQL',sql)
 try:
  for x in nm.query(sql)['rows']: print(x)
 except Exception as e: print(e)

