out={}
# Age-330 outcomes were catastrophic and highly cohort-specific (43/44 retained ~39-42%,
# 45 retained 13%, and 46-48 retained <2%). Preserve the strongest economically viable
# B4 quality; B5's +10% costs 2.5x per token and cannot bridge the new ~0.45 expectation shock.
out['prices']=nm.pricing.set_prices(A=20,B=59,C=149)
out['tiers']=nm.pricing.set_model_tiers(A=2,B=4,C=4)
out['quotas']=nm.pricing.set_usage_quotas(A=300,B=1000,C=1000)
# Peak was 2.27m against T3's 2.5m, no overload. Keep T3 this week because the large
# starts49-55 book remains live through the early-week peaks; reconsider T2 only below 0.8m.
out['capacity']=nm.infrastructure.set_capacity_tier(tier=3)
# $12k still resolves every active-account ticket the next day. Taper to $10k in line
# with the 21.5% subscriber decline while maintaining a wide ~3k/day throughput buffer.
out['spend']=nm.marketing.set_daily_spend(operations=10000,development=0)
out['target_ops']=nm.analytics.set_targeted_ops_spend(targeted_spend={})
out['target_dev']=nm.analytics.set_targeted_dev_spend(targeted_spend={})
# Organic conversion was 0/542 and recent first renewals fail. Do not buy CAC, discount,
# or add an in-app-ad quality penalty while the valuable mature cohorts are at renewal risk.
out['ads']=nm.marketing.set_targeted_ad_spend(targeted_spend={})
out['ads_strength']=nm.marketing.set_ads_strength(global_strength=0.0,by_group={},by_customer={})
out['lead_promo']=nm.marketing.set_lead_promotion(global_promotion=0.0,by_group={'S1':0.0,'S2':0.0,'S3':0.0,'E1':0.0,'E2':0.0,'E3':0.0},by_channel={},by_channel_group={})
out['promotion']=nm.pricing.set_promotion(global_promotion=0.0,by_group={'S1':0.0,'S2':0.0,'S3':0.0,'E1':0.0,'E2':0.0,'E3':0.0},by_customer={},by_group_plan={})
# Prior post was positive and there is no fresh individual complaint after it; avoid
# diverting attention from a four-day wave of rival launch posts with unverifiable claims.
for k,v in out.items(): print(k,json.dumps(v,indent=2) if isinstance(v,(dict,list)) else v)
