arguments.command:
./novamind-operation python-c "import novamind_api as nm
qs={
'ledger_week':\"SELECT category, SUM(amount) amount, COUNT(*) n FROM ledger WHERE day>413 GROUP BY category ORDER BY category\",
'ledger_day':\"SELECT day, category, SUM(amount) amount FROM ledger WHERE day>413 GROUP BY day,category ORDER BY day,category\",
'subs':\"SELECT status, COUNT(*) n FROM subscriptions GROUP BY status\",
'active_ent':\"SELECT COUNT(*) n, COALESCE(SUM(seats),0) seats FROM subscriptions WHERE status='subscribed' AND customer_id IN (SELECT customer_id FROM customers WHERE customer_type='enterprise')\",
'pending_recent':\"SELECT COUNT(*) n FROM enterprise_turns WHERE closed=0 AND day>=413\"
}
print('day',nm.vars.current_day)
for k,q in qs.items():
 try: print(k,nm.query(q)['rows'])
 except Exception as e: print(k,'ERR',e)
print('cost',nm.infrastructure.get_cost_info())
print('research',nm.research.list_research_projects())"

