arguments.command:
./novamind-operation python-c "import novamind_api as nm
queries=[
\"SELECT SUM(amount) cash FROM ledger\",
\"SELECT day,category,amount,note FROM ledger ORDER BY id DESC LIMIT 20\",
\"SELECT COUNT(*) n FROM subscriptions WHERE status='subscribed'\",
\"SELECT COUNT(*) n, COALESCE(SUM(seat_count),0) seats FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND c.customer_type='enterprise'\",
\"SELECT COUNT(*) n FROM enterprise_turns WHERE closed=0 AND day>=414\"
]
for q in queries:
 try: print(q, nm.query(q)['rows'])
 except Exception as e: print('ERR',e)
"

