queries={'active_subs':\"SELECT COUNT(*) n FROM subscriptions WHERE status='subscribed'\",'new_customers':\"SELECT COUNT(*) n FROM customers WHERE signup_day>=442\",'new_turns':\"SELECT COUNT(*) n FROM enterprise_turns WHERE day>=442\",'ledger':\"SELECT MIN(day) min_day, MAX(day) max_day, COUNT(*) n, SUM(amount) total FROM ledger WHERE day>=442\",'ledger_detail':\"SELECT day, category, amount, note FROM ledger WHERE day>=442 ORDER BY day\"}
for k,q in queries.items():
 try: print(k,nm.query(q)['rows'])
 except Exception as e: print(k,'ERR',e)
print('cost_info',nm.infrastructure.get_cost_info())
print('research',nm.research.list_research_projects())
print('day',nm.vars.current_day)"

